import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"X 射线与近场","description":"","frontmatter":{"title":"X 射线与近场","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/xray-near-field.md","filePath":"litho/xray-near-field.md","lastUpdated":1789023840000}'),E={name:"litho/xray-near-field.md"};function A(c,a,B,_,m,f){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="x-射线与近场" tabindex="-1">X 射线与近场 <a class="header-anchor" href="#x-射线与近场" aria-label="Permalink to &quot;X 射线与近场&quot;">​</a></h1><div class="epigraph"><p>更短的波长在 1980–90 年代走过接近式 X 射线；掩模、间隙与源让它让位给延长寿命的 193 nm。近场则用倏逝波，焦深薄到几乎不是扫描机。</p><footer>—— 对照 X-ray lithography（IBM 等传统）与近场/倏逝光刻的公开历史</footer></div><p><a href="/litho/interference-lithography">上一课</a>展示无透镜周期。缺口是短波接近式与倏逝。本课钉 X 射线与近场。封装尺度的激光直写，留给[下一课](/litho/laser-direct-write-packaging）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接近式 X 射线光刻：掩模贴近晶圆，用同步辐射或等离子源，分辨率好，工业上卡在掩模（吸收体、支架）、间隙控制、源与对准。193 浸没 + RET + 多重在成本上赢了，路线被放弃为逻辑主路径。近场/表面等离子体光刻：突破远场衍射，但工作距离纳米级，不适合晶圆扫描产能与形貌。</p><p>缺口是<strong>历史岔路</strong>，不是再推瑞利去证明 X 射线「应该赢」。课程要记住：更短 λ 不是充分条件。</p><h3 id="liga-与-mems" tabindex="-1">LIGA 与 MEMS <a class="header-anchor" href="#liga-与-mems" aria-label="Permalink to &quot;LIGA 与 MEMS&quot;">​</a></h3><p>厚胶 X 射线在 MEMS/LIGA 仍有尼奇，对象是高 AR 金属结构，不是 CMOS 金属节距。后课 MEMS 会点到。</p><p><span class="marginnote">EUV 是反射投影，不是 1990s 接近式 X 射线的复活。不要把两者混成「都是短波所以一样」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读史：为何 157 nm 与 X 射线让位浸没。近场：实验室演示 vs 晶圆 wph 算术（工作距离、平整度）。评估替代技术时沿用同一算术。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>接近式衍射与半影随间隙变；间隙要小，颗粒与形貌不可忍——pellicle 逻辑的反面。近场强度随距离指数衰减，台阶直接毁掉均匀性。投影光学把掩模放到远处共轭，正是为了躲这两者。</p>',13)),(e(),s(p,null,{default:r(()=>[h(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20XR%5B%22%E6%8E%A5%E8%BF%91%E5%BC%8F%20X%20%E5%B0%84%E7%BA%BF%22%5D%20--%3E%20MASK%5B%22%E6%8E%A9%E6%A8%A1%20%2F%20%E9%97%B4%E9%9A%99%20%2F%20%E6%BA%90%E5%A2%99%22%5D%0A%20%20NF%5B%22%E8%BF%91%E5%9C%BA%E5%80%8F%E9%80%9D%22%5D%20--%3E%20GAP%5B%22%E5%B7%A5%E4%BD%9C%E8%B7%9D%E7%A6%BB%E5%A2%99%22%5D%0A%20%20PROJ%5B%22%E6%8A%95%E5%BD%B1%E5%85%89%E5%AD%A6%22%5D%20--%3E%20FAR%5B%22%E8%BF%9C%E5%9C%BA%E5%85%B1%E8%BD%AD%20%2B%20%E4%BA%A7%E8%83%BD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不宣布近场永远无用（存储、模板可能）。不把同步辐射当已死的科学。本课不重开 EUV 源物理。</p><p>后课默认：短波接近式不是先进 CMOS 主路；下一课波长更长、场更大的封装激光直写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>接近式 X 射线卡在掩模、间隙与源，被 193 路径取代为逻辑主线。</li><li>近场破远场衍射，工作距离与形貌不适合扫描产线。</li><li>EUV 投影 ≠ 接近式 X 射线。</li><li>出处：X-ray lithography 产业史；近场光刻实验室传统。</li></ul>',5))])}const D=l(E,[["render",A]]);export{x as __pageData,D as default};
